// Reference utility silhouettes retain their 24px geometry; Aux brand marks are separate.
import { createElement, type ComponentType, type ReactElement, type ReactNode, type SVGProps } from "react";
import { nativeAriaHiddenProps as auxNativeAriaHiddenProps } from "./native-attribute-props";

type Props = SVGProps<SVGSVGElement>;

const baseSvgProps = {
  width: "1em",
  height: "1em",
  "aria-hidden": "true",
  xmlns: "http://www.w3.org/2000/svg",
  viewBox: "0 0 24 24",
  fill: "none",
  strokeLinecap: "round",
  strokeLinejoin: "round",
} as const;

const strokeProps = { stroke: "currentColor", strokeWidth: "2" } as const;

const roundStrokeProps = { ...strokeProps, strokeLinecap: "round" } as const;

const joinedStrokeProps = { ...strokeProps, strokeLinejoin: "round" } as const;

const roundJoinedStrokeProps = { ...roundStrokeProps, strokeLinejoin: "round" } as const;

type IcoSize = "sm" | "md" | "lg";

function icon(
  Icon: ComponentType<SVGProps<SVGSVGElement>>,
  size: IcoSize = "md",
  fill = "none",
): ReactElement {
  return (
    <span className={`ci ico-${size}`} aria-hidden>
      <Icon fill={fill} />
    </span>
  );
}

function svg(props: SVGProps<SVGSVGElement>, ...children: ReactNode[]): ReactElement {
  return createElement("svg", { ...baseSvgProps, ...props }, ...children);
}

function svgPath(
  d: string,
  stroke: Pick<
    SVGProps<SVGPathElement>,
    "stroke" | "strokeWidth" | "strokeLinecap" | "strokeLinejoin"
  > = roundJoinedStrokeProps,
): ReactElement {
  return createElement("path", { d, ...stroke });
}

